export function getAirportsByCountry(countryCode: string): Airport[] {
  return AIRPORTS_BY_COUNTRY[countryCode] || [];
}

const byIata = new Map<string, Airport & { country: string }>();
for (const [country, list] of Object.entries(AIRPORTS_BY_COUNTRY)) {
  for (const a of list) byIata.set(a.code, { ...a, country });
}

export function findAirportByIata(code: string): (Airport & { country: string }) | undefined {
  return byIata.get((code || "").toUpperCase());
}

export function airportLabel(code: string): string {
  const a = findAirportByIata(code);
  return a ? `${a.name} (${a.code})${a.city ? `, ${a.city}` : ""}` : code;
}
